// _journal_sizeSliceSliceByte returns the length of the encoding of the
// elements of x, a [][]byte.
func _journal_sizeSliceSliceByte(x [][]byte) int {
	n := 0
	for k := range x {
		n += wire.SizeBytes(len(x[k]))
	}
	return n
}

// _journal_putSliceSliceByte writes the encoding of x, a [][]byte, into the end
// of buf, which has room for it, and returns its length.
func _journal_putSliceSliceByte(buf []byte, x [][]byte) int {
	i := len(buf)
	for k := len(x) - 1; k >= 0; k-- {
		i = wire.PutRaw(buf, i, x[k])
		i = wire.PutUvarint(buf, i, uint64(len(x[k])))
	}
	i = wire.PutUvarint(buf, i, uint64(len(buf)-i))
	return len(buf) - i
}

// _journal_readSliceSliceByte appends the elements that data encodes, a
// [][]byte without its length, to *dst. data starts at offset off of slab, and
// the decode enters depth levels below the value at most. loc and num locate
// the field in errors.
func _journal_readSliceSliceByte(dst *[][]byte, data []byte, slab string, off, depth int, loc string, num int) error {
	if depth < 0 {
		return wire.DepthError(loc, num, off)
	}
	x := *dst
	if x == nil && len(data) > 0 {
		x = make([][]byte, 0, wire.CountValues(data))
	}
	for i := 0; i < len(data); {
		if len(x) < cap(x) {
			x = x[:len(x)+1]
		} else {
			x = append(x, nil)
		}
		last := len(x) - 1
		l, n := wire.Uvarint(data[i:])
		if n <= 0 || uint64(len(data)-i-n) < l {
			return wire.ReadError(n, loc, num, off+i)
		}
		if n > 1 && data[i+n-1] == 0 {
			return wire.LongFormError(n, loc, num, off+i)
		}
		i += n
		x[last] = append(x[last][:0], data[i:i+int(l)]...)
		i += int(l)
	}
	*dst = x
	return nil
}

